                var baseState = new { position = V(origin), direction = new[] { MathF.Atan2(forward.X, forward.Z), MathF.Asin(Math.Clamp(-forward.Y, -1, 1)), MathF.Atan2(right.Y, up.Y) },
                    speed = Vector3.Dot(velocity, forward), rspeed = angular.Y, contacts = Enumerable.Range(0, 6).Count(i => constraint.GetWheel(i).HasContact),
                    linear_velocity = V(velocity), angular_velocity = V(angular), wheel_contact_masks = contactMasks.ToArray() };
                if (angularFracture != null)
                {
                    angularBinding!.Verify(body);
                    return new { baseState.position, baseState.direction, baseState.speed, baseState.rspeed, baseState.contacts,
                        baseState.linear_velocity, baseState.angular_velocity, baseState.wheel_contact_masks,
                        object_contacts = publishedContacts.Select(c => new { object_id = c.ObjectId, kind = c.Kind,
                            substep = c.Substep, point = V(c.Point), normal = V(c.Normal), velocity = V(c.Velocity) }).ToArray(),
                        fractures = angularFracture.Receipts.Select(r => r.ToWire()).ToArray(),
                        body_binding = angularBinding.ToWire(), motion_witnesses = angularFracture.Witnesses.Select(w => w.ToWire()).ToArray() };
                }
                if (fracture != null)
                    return new { baseState.position, baseState.direction, baseState.speed, baseState.rspeed, baseState.contacts,
                        baseState.linear_velocity, baseState.angular_velocity, baseState.wheel_contact_masks,
                        object_contacts = publishedContacts.Select(c => new { object_id = c.ObjectId, kind = c.Kind,
                            substep = c.Substep, point = V(c.Point), normal = V(c.Normal), velocity = V(c.Velocity) }).ToArray(),
                        fractures = fracture.Receipts.Select(r => new { object_id = r.ObjectId, substep = r.Substep, order = r.Order,
                            point = V(r.Point), normal = V(r.Normal), velocity = V(r.Velocity), budget_before = V(r.BudgetBefore),
                            budget_after = V(r.BudgetAfter), solver_before = V(r.SolverBefore), solver_after = V(r.SolverAfter), energy_j = r.EnergyJ }).ToArray() };
                if (catalog?.Contacts == true)
                    return new { baseState.position, baseState.direction, baseState.speed, baseState.rspeed, baseState.contacts,
                        baseState.linear_velocity, baseState.angular_velocity, baseState.wheel_contact_masks,
                        object_contacts = publishedContacts.Select(c => new { object_id = c.ObjectId, kind = c.Kind,
                            substep = c.Substep, point = V(c.Point), normal = V(c.Normal), velocity = V(c.Velocity) }).ToArray() };
                return baseState;
            }
            void Write(string eventName)
            {
                diagnostics?.Write(sequence, tick, bodies.GetRotation(body.ID), bodies.GetLinearVelocity(body.ID),
                    bodies.GetAngularVelocity(body.ID), controller, constraint);
                if (angularFracture != null)
                {
                    var line = CheckedInput.AngularLine(new { version = catalog!.IpcVersion, @event = eventName, seq = sequence,
                        tick, settle_ticks = 180, map, config_sha256 = hash, generation, catalog_sha256 = catalog.Hash,
                        scene_version = sceneVersion, scene_sha256 = scene!.Hash, contacts = true, state = State() });
                    angularOutput!.Write(line); return;
                }
                if (catalog != null)
                    Console.WriteLine(JsonSerializer.Serialize(new { version = catalog.IpcVersion, @event = eventName, seq = sequence,
                        tick, settle_ticks = 180, map, config_sha256 = hash, generation, catalog_sha256 = catalog.Hash,
                        scene_version = sceneVersion, scene_sha256 = scene!.Hash, contacts = catalog.Contacts ? true : (bool?)null, state = State() },
                        new JsonSerializerOptions { DefaultIgnoreCondition = System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull }));
                else if (removal == null)
                    Console.WriteLine(JsonSerializer.Serialize(new { version = 1, @event = eventName, seq = sequence,
                        tick, settle_ticks = 180, map, config_sha256 = hash, state = State() }));
                else
                    Console.WriteLine(JsonSerializer.Serialize(new { version = 2, @event = eventName, seq = sequence,
                        tick, settle_ticks = 180, map, config_sha256 = hash, generation, descriptor_sha256 = removal.DescriptorHash,
                        object_id = removal.ObjectId, object_revision = removal.Revision, scene_version = sceneVersion, state = State() }));
            }
            Advance(0, 0, true, 180);
            if (Enumerable.Range(0, 6).Count(i => constraint.GetWheel(i).HasContact) < 3 || bodies.GetLinearVelocity(body.ID).Length() > 1)
                throw new InvalidOperationException("spawn failed to settle on imported geometry");
            Write("ready");
            for (byte[]? line; (line = CheckedInput.ReadLine(input, ipcLimit)) != null;)
            {
                using var command = CheckedInput.IpcJson(line, angularBinding != null);
                var request = command.RootElement;
                if (catalog != null && request.GetProperty("op").GetString() == "sync_removed")
                {
                    var next = CheckedInput.SceneCommand(request, "sync_removed", catalog, generation, hash, sequence);
                    if (scene!.Ids.Any(id => !next.Ids.Contains(id))) throw new InvalidDataException("scene removal cannot be reversed");
                    if (pendingLocal.Any(id => !next.Ids.Contains(id))) throw new InvalidDataException("scene commit omits prepared fracture");
                    var delta = next.Ids.Where(id => !scene.Ids.Contains(id)).ToArray();
                    // Validate the complete delta before any native mutation.
                    if (delta.Any(id => !catalogBodies.TryGetValue(id, out var bodyId) || !staticBodies.Contains(bodyId)))
                        throw new InvalidOperationException("catalog body unavailable");
                    foreach (uint id in delta)
                    {
                        var bodyId = catalogBodies[id];
                        if (pendingLocal.Contains(id)) bodies.DestroyBody(bodyId);
                        else bodies.RemoveAndDestroyBody(bodyId);
                        pendingLocal.Remove(id);
                        staticBodies.Remove(bodyId); catalogBodies.Remove(id);
                    }
                    scene = next; sceneVersion = next.Version;
                    var acknowledgement = new { version = catalog.IpcVersion, @event = "scene_synced", advance_seq = sequence,
                        tick, generation, config_sha256 = hash, catalog_sha256 = catalog.Hash,
                        scene_version = sceneVersion, removed_object_ids = scene.Ids, scene_sha256 = scene.Hash,
                        contacts = catalog.Contacts ? true : (bool?)null };
                    if (angularOutput != null) angularOutput.Write(CheckedInput.AngularLine(acknowledgement));
                    else Console.WriteLine(JsonSerializer.Serialize(acknowledgement,
                        new JsonSerializerOptions { DefaultIgnoreCondition = System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull }));
                    continue;
                }
                if (removal != null && request.GetProperty("op").GetString() == "remove_one")
                {
                    CheckedInput.Fields(request, "version", "op", "mutation_seq", "expected_scene_version", "scene_version", "generation",
                        "object_id", "object_revision", "descriptor_sha256", "config_sha256", "advance_seq");
                    if (request.GetProperty("version").GetInt32() != 2 || request.GetProperty("mutation_seq").GetInt32() != 1 ||
                        request.GetProperty("expected_scene_version").GetInt32() != 0 || request.GetProperty("scene_version").GetInt32() != 1 ||
                        request.GetProperty("generation").GetUInt32() != generation || request.GetProperty("object_id").GetUInt32() != removal.ObjectId ||
                        request.GetProperty("object_revision").GetString() != removal.Revision || request.GetProperty("descriptor_sha256").GetString() != removal.DescriptorHash ||
                        request.GetProperty("config_sha256").GetString() != hash || request.GetProperty("advance_seq").GetInt64() != sequence)
                        throw new InvalidDataException("one-object removal identity/version mismatch");
                    if (sceneVersion == 0)
                    {
                        if (selectedBody is not BodyID id || !staticBodies.Contains(id)) throw new InvalidOperationException("selected body unavailable");
                        bodies.RemoveAndDestroyBody(id);
                        staticBodies.Remove(id); selectedBody = null; sceneVersion = 1;
                    }
                    // Repeating this exact mutation is idempotent; no simulation tick or driving sequence is consumed.
                    Console.WriteLine(JsonSerializer.Serialize(new { version = 2, @event = "removed", mutation_seq = 1, advance_seq = sequence,
                        tick, generation, config_sha256 = hash, descriptor_sha256 = removal.DescriptorHash,
                        object_id = removal.ObjectId, object_revision = removal.Revision, scene_version = sceneVersion }));
                    continue;
                }
                if (catalog?.Contacts == true) CheckedInput.Fields(request, "version", "op", "seq", "ticks", "input", "scene_version", "scene_sha256", "contacts");
                else if (catalog != null) CheckedInput.Fields(request, "version", "op", "seq", "ticks", "input", "scene_version", "scene_sha256");
                else if (removal == null) CheckedInput.Fields(request, "version", "op", "seq", "ticks", "input");
                else CheckedInput.Fields(request, "version", "op", "seq", "ticks", "input", "scene_version");
                if (pendingLocal.Count != 0) throw new InvalidDataException("advance requires prepared fracture commit");
                if (request.GetProperty("version").GetInt32() != (catalog?.IpcVersion ?? (removal == null ? 1 : 2)) || request.GetProperty("op").GetString() != "advance" ||
                    (catalog?.Contacts == true && request.GetProperty("contacts").ValueKind != JsonValueKind.True) ||
                    (descriptorEnabled && request.GetProperty("scene_version").GetUInt32() != sceneVersion) ||
                    (catalog != null && request.GetProperty("scene_sha256").GetString() != scene!.Hash) ||
                    request.GetProperty("seq").GetInt64() != sequence + 1 || sequence >= 36000 || request.GetProperty("ticks").GetInt32() != 6)
                    throw new InvalidDataException("IPC sequence or cadence mismatch");
                var controls = request.GetProperty("input"); CheckedInput.Fields(controls, "throttle", "steer", "brake");
                int throttle = controls.GetProperty("throttle").GetInt32(), steer = controls.GetProperty("steer").GetInt32();
                bool brake = controls.GetProperty("brake").GetBoolean();
                if (Math.Abs((long)throttle) > 1 || Math.Abs((long)steer) > 1 || (brake && (throttle != 0 || steer != 0)))
                    throw new InvalidDataException("invalid domain driving input");
                rawContactCount = 0; contactOverflow = 0; currentSubstep = 0;
                while (rawContacts.TryDequeue(out _)) { }
                fracture?.BeginAdvance();
                angularFracture?.BeginAdvance();
                captureContactsEnabled = catalog?.Contacts == true;
                Advance(throttle, steer, brake, 6, catalog?.Contacts == true);
                captureContactsEnabled = false;
                CollectContacts(); sequence++; Write(fracture?.Receipts.Count > 0 || angularFracture?.Receipts.Count > 0 ? "prepared" : "state");
            }
        }
        finally
        {
            world.RemoveStepListener(constraint); world.RemoveConstraint(constraint);
            bodies.RemoveAndDestroyBody(body.ID);
            foreach (var id in staticBodies)
                if (catalogBodies.Any(entry => entry.Value == id && pendingLocal.Contains(entry.Key))) bodies.DestroyBody(id);
                else bodies.RemoveAndDestroyBody(id);
            foreach (var wheel in wheels) wheel.Dispose();
        }
    }
    finally { Foundation.Shutdown(); }
    return 0;
}
catch (Exception error)
{
    // Failure is visible to the parent, never returned as a valid state.
    Console.Error.WriteLine(JsonSerializer.Serialize(new { @event = "worker_error", type = error.GetType().Name, message = error.Message }));
    return 1;
}

readonly record struct RawContact(uint Body1, uint Body2, Vector3 Point, Vector3 Normal, Vector3 Velocity, int Substep, string Kind);
readonly record struct ContactRecord(uint ObjectId, string Kind, int Substep, Vector3 Point, Vector3 Normal, Vector3 Velocity);
